  "The %g%% %s for %s is [%s, %s]. The H0 value %s is %s the interval, so %s H0." = "الفترة $2 بمستوى $1% لـ$3 هي [$4، $5]. وقيمة H0 وهي $6 تقع $7 الفترة، لذا $8 H0.",
  "%g%% %s intervals for every difference of two %s: %d of %d exclude 0. %s" = "فترات $2 بمستوى $1% لكل فرق بين $3: تستبعد $4 من $5 فترة الصفر. $6",
